def rss_bytes(): # Sample the process resident set without adding an optional package dependency.
    fields=Path('/proc/self/status').read_text().splitlines();line=next(line for line in fields if line.startswith('VmRSS:'));return int(line.split()[1])*1024 # Linux reports VmRSS in KiB.
class MemorySample: # Measure phase-local RSS while retaining the separate process high-water mark.
    def __enter__(self): # Start a lightweight memory sampler before the measured operation.
        self.start=rss_bytes();self.peak=self.start;self.stop=threading.Event();self.thread=threading.Thread(target=self.sample,daemon=True);self.thread.start();return self # Sampling does not perform numerical computation.
    def sample(self): # Observe the resident set throughout the operation.
        while not self.stop.wait(.01): self.peak=max(self.peak,rss_bytes()) # Ten-millisecond sampling can miss shorter allocation peaks, so also retain ru_maxrss.
    def __exit__(self,*unused): # Finish sampling even if an actual graph operation fails.
        self.stop.set();self.thread.join();self.end=rss_bytes();self.peak=max(self.peak,self.end);self.lifetime_peak=int(resource.getrusage(resource.RUSAGE_SELF).ru_maxrss)*1024 # Report the authoritative Linux process high-water mark as well.
    def report(self): # Express each memory measure with unambiguous units and scope.
        return {'rss_start_bytes':self.start,'rss_end_bytes':self.end,'sampled_phase_peak_rss_bytes':self.peak,'process_lifetime_peak_rss_bytes':self.lifetime_peak,'sample_interval_seconds':.01} # Phase-local sampled peaks and lifetime peaks are not interchangeable.
def weights_sha(model): # Identify random initial weights and disposable timing-only updated weights.
    digest=hashlib.sha256() # No model file is created by this benchmark.
    for name,value in model.state_dict().items(): digest.update(name.encode());digest.update(value.detach().cpu().numpy().tobytes()) # Include exact parameter names and bytes.
    return digest.hexdigest() # The hash proves that actual optimization occurred without publishing a predictor.
def curriculum(epochs,steps): # Count the exact base temporal curriculum without opening any other field data.
    counts={'two_step_epochs':epochs//3,'four_step_epochs':2*epochs//3-epochs//3,'full_history_epochs':epochs-2*epochs//3} # Match the integer cutoffs in the current base training function.
    counts['recurrent_steps_per_case']=counts['two_step_epochs']*2+counts['four_step_epochs']*4+counts['full_history_epochs']*steps;counts['validation_checks']=len(set(list(range(0,epochs,20))+[epochs-1]));return counts # Preserve the exact number of planned validation checkpoints.
